CREATE TABLE forma.routine_exercises (id uuid PRIMARY KEY, routine_id uuid NOT NULL REFERENCES forma.routines(id) ON DELETE CASCADE, exercise_source text NOT NULL, exercise_id text NOT NULL, exercise_name_snapshot text NOT NULL, "order" integer NOT NULL, target_sets integer NOT NULL CHECK(target_sets BETWEEN 1 AND 20), target_reps integer NOT NULL CHECK(target_reps BETWEEN 1 AND 1000), rest_seconds integer NOT NULL CHECK(rest_seconds BETWEEN 0 AND 3600), notes text);
CREATE INDEX routine_exercises_routine_id_order_idx ON forma.routine_exercises(routine_id,"order");
CREATE TABLE forma.workout_exercises (id uuid PRIMARY KEY, workout_id uuid NOT NULL REFERENCES forma.workouts(id) ON DELETE CASCADE, exercise_source text NOT NULL, exercise_id text NOT NULL, exercise_name_snapshot text NOT NULL, "order" integer NOT NULL, notes text);
CREATE INDEX workout_exercises_workout_id_order_idx ON forma.workout_exercises(workout_id,"order");
CREATE TABLE forma.workout_sets (id uuid PRIMARY KEY, workout_exercise_id uuid NOT NULL REFERENCES forma.workout_exercises(id) ON DELETE CASCADE, set_number integer NOT NULL, weight_kg numeric(8,2), repetitions integer NOT NULL CHECK(repetitions BETWEEN 0 AND 10000), completed boolean NOT NULL DEFAULT false, completed_at timestamp(3), created_at timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamp(3) NOT NULL, UNIQUE(workout_exercise_id,set_number));
ALTER TABLE forma.routine_exercises ENABLE ROW LEVEL SECURITY;
ALTER TABLE forma.workout_exercises ENABLE ROW LEVEL SECURITY;
ALTER TABLE forma.workout_sets ENABLE ROW LEVEL SECURITY;
CREATE POLICY routine_exercises_own ON forma.routine_exercises USING (EXISTS (SELECT 1 FROM forma.routines r WHERE r.id=routine_id AND r.user_id=(select auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM forma.routines r WHERE r.id=routine_id AND r.user_id=(select auth.uid())));
CREATE POLICY workout_exercises_own ON forma.workout_exercises USING (EXISTS (SELECT 1 FROM forma.workouts w WHERE w.id=workout_id AND w.user_id=(select auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM forma.workouts w WHERE w.id=workout_id AND w.user_id=(select auth.uid())));
CREATE POLICY workout_sets_own ON forma.workout_sets USING (EXISTS (SELECT 1 FROM forma.workout_exercises e JOIN forma.workouts w ON w.id=e.workout_id WHERE e.id=workout_exercise_id AND w.user_id=(select auth.uid()))) WITH CHECK (EXISTS (SELECT 1 FROM forma.workout_exercises e JOIN forma.workouts w ON w.id=e.workout_id WHERE e.id=workout_exercise_id AND w.user_id=(select auth.uid())));
